DO $$
BEGIN
    IF to_regclass('telephony.calls') IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = to_regclass('telephony.calls') AND conname = 'ck_calls_from_number_required__required') THEN
        IF EXISTS (SELECT 1 FROM telephony.calls WHERE NOT ((from_number IS NOT NULL AND btrim(from_number::text) <> ''))) THEN
            RAISE NOTICE 'ck_calls_from_number_required__required not added: stored rows of telephony.calls break it';
        ELSE
            ALTER TABLE telephony.calls ADD CONSTRAINT ck_calls_from_number_required__required CHECK ((from_number IS NOT NULL AND btrim(from_number::text) <> ''));
        END IF;
    END IF;
EXCEPTION WHEN undefined_column THEN
    RAISE NOTICE 'ck_calls_from_number_required__required not added: telephony.calls lacks a column it reads';
END $$;

